  const string Request="Assets/Editor/CQC/RepairCastleCrowd750-v2.request.txt";static double next;
  static RedistributeCastleCrowd(){EditorApplication.update+=Pending;}
  static void Pending(){if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+1;if(!File.Exists(Request)||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||SceneManager.GetActiveScene().name!="MyForest")return;Undo.IncrementCurrentGroup();int group=Undo.GetCurrentGroup();try{Apply();Undo.CollapseUndoOperations(group);AssetDatabase.DeleteAsset(Request);}catch(Exception e){Undo.RevertAllDownToGroup(group);Directory.CreateDirectory("Logs");File.WriteAllText("Logs/RedistributeCastleCrowd-error.txt",e.ToString());Debug.LogException(e);AssetDatabase.MoveAsset(Request,Request+"."+DateTime.Now.ToString("yyyyMMddHHmmss")+".failed");}}
  [MenuItem("Tools/NPC/Move Majority Inside Castle And Connect Transport")]
  public static void Apply()
  {
   var root=GameObject.Find("Synty Walking Castle And City Population 750");if(!root)root=GameObject.Find("Synty Walking City Population 1500");if(!root)throw new InvalidOperationException("Install Synty population first.");var crowd=root.GetComponent<CityCrowdManager>();var mountain=GameObject.Find("Castle Mountain");var city=GameObject.Find("Lower Castle City");var elevator=mountain.GetComponentInChildren<CastleElevator>();var funicular=mountain.GetComponentInChildren<CastleFunicular>();if(!funicular)funicular=UnityEngine.Object.FindAnyObjectByType<CastleFunicular>();if(!elevator||!funicular)throw new InvalidOperationException("Elevator and funicular required.");
   var outside=city.transform.Find("Winding Roads and Market Square");var castleRoads=mountain.transform.Find("Connected Castle Stone Roads");var lower=mountain.transform.Find("Cobblestone Castle Floors/Outer House Floor").GetComponent<MeshCollider>();var upper=mountain.transform.Find("Inner Castle Mountain/Flat Inner Castle Floor").GetComponent<MeshCollider>();var bridge=mountain.transform.Find("Castle Scaffold Elevator/Upper Landing Bridge");if(!outside||!castleRoads||!lower||!upper||!bridge)throw new InvalidOperationException("Castle floors, roads and landing bridge required.");
   var scene=SceneManager.GetActiveScene();string stamp=DateTime.Now.ToString("yyyyMMdd-HHmmss"),backup="Assets/ForestExpansion/Backups/MyForest-before-castle-npcs-"+stamp+".unity";if(!EditorSceneManager.SaveScene(scene,backup,true))throw new IOException("Backup failed.");string folder="Assets/CityExpansion/CastleCrowd-"+stamp;Directory.CreateDirectory(folder);AssetDatabase.Refresh();Physics.SyncTransforms();
   var roleSkins=crowd.People.Select(p=>p.Skin).ToArray();var roleNames=crowd.People.Select(p=>p.Role).ToArray();var original=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Where(t=>!t.IsChildOf(root.transform)&&t!=root.transform).ToArray();var matrices=original.Select(t=>t.localToWorldMatrix).ToArray();var bounds=lower.bounds;bounds.Encapsulate(upper.bounds);foreach(var r in outside.GetComponentsInChildren<Renderer>())bounds.Encapsulate(r.bounds);bounds.Expand(new Vector3(16,12,16));var markup=new List<NavMeshBuildMarkup>();foreach(var t in new[]{outside,lower.transform,upper.transform,bridge})markup.Add(new NavMeshBuildMarkup{root=t,overrideArea=true,area=0});foreach(var t in funicular.GetComponentsInChildren<Transform>())if(t.name=="Lower Boarding Platform"||t.name=="Upper Castle Boarding Bridge"||t.name.StartsWith("Forest Access Step "))markup.Add(new NavMeshBuildMarkup{root=t,overrideArea=true,area=0});foreach(var t in funicular.Carts)markup.Add(new NavMeshBuildMarkup{root=t,ignoreFromBuild=true});markup.Add(new NavMeshBuildMarkup{root=elevator.Platform,ignoreFromBuild=true});
   var sources=new List<NavMeshBuildSource>();NavMeshBuilder.CollectSources(bounds,~0,NavMeshCollectGeometry.PhysicsColliders,1,markup,sources);sources.RemoveAll(s=>s.shape==NavMeshBuildSourceShape.Terrain||(s.component&&s.component.name.StartsWith("ForestGround")));var access=BuildStationGroundApproach(funicular,outside);sources.Add(new NavMeshBuildSource{shape=NavMeshBuildSourceShape.Mesh,sourceObject=access,transform=Matrix4x4.identity,area=0});var settings=NavMesh.GetSettingsByIndex(0);settings.agentRadius=.3f;settings.agentHeight=1.8f;settings.agentClimb=.3f;settings.overrideVoxelSize=true;settings.voxelSize=.12f;var data=NavMeshBuilder.BuildNavMeshData(settings,sources,bounds,Vector3.zero,Quaternion.identity);UnityEngine.Object.DestroyImmediate(access);if(!data)throw new InvalidOperationException("Navigation bake failed.");AssetDatabase.CreateAsset(data,folder+"/CastleAndCityNavigation.asset");var temp=NavMesh.AddNavMeshData(data);
   try
   {
    var nodes=new List<Vector3>();var regions=new List<int>();var routes=new List<CityCrowdRoute>();var counts=new List<int>();for(int region=0;region<3;region++)
    {
     var candidates=new List<Vector3>();var filters=region==0?outside.GetComponentsInChildren<MeshFilter>().Where(IsStreetGuide).ToArray():castleRoads.GetComponentsInChildren<MeshFilter>().Where(f=>f.name.StartsWith(region==1?"Lower":"Upper")).ToArray();foreach(var f in filters){var vertices=f.sharedMesh.vertices;for(int i=0;i+1<vertices.Length;i+=12){var p=f.transform.TransformPoint((vertices[i]+vertices[i+1])*.5f);if(NavMesh.SamplePosition(p,out NavMeshHit hit,1.7f,1)&&Mathf.Abs(hit.position.y-p.y)<1.2f&&candidates.All(n=>Vector3.Distance(n,hit.position)>3))candidates.Add(hit.position);}}
     var components=new List<List<Vector3>>();while(candidates.Count>0){var seed=candidates[0];var component=new List<Vector3>();foreach(var point in candidates.ToArray()){var path=new NavMeshPath();if(NavMesh.CalculatePath(seed,point,1,path)&&path.status==NavMeshPathStatus.PathComplete){component.Add(point);candidates.Remove(point);}}if(component.Count==0)candidates.Remove(seed);else components.Add(component);}var connected=components.OrderByDescending(c=>c.Count).FirstOrDefault();if(connected==null||connected.Count<8)throw new InvalidOperationException("Too few connected road locations in region "+region);int offset=nodes.Count;nodes.AddRange(connected);regions.AddRange(connected.Select(n=>region));counts.Add(connected.Count);
     for(int from=offset;from<nodes.Count;from++){foreach(int to in Enumerable.Range(offset,connected.Count).Where(i=>i!=from).OrderBy(i=>Vector3.Distance(nodes[i],nodes[from])).Take(5)){var path=PathBetween(nodes[from],nodes[to]);routes.Add(new CityCrowdRoute{From=from,To=to,Region=region,Transfer=-1,Corners=path,Length=Length(path)});}}
    }
    AddCircuits(nodes,regions,routes);var transfers=new List<CityCrowdTransfer>();ConnectTransport(0,1,2,elevator.LowerCallPoint,elevator.UpperCallPoint,nodes,regions,routes,transfers);ConnectTransport(1,0,1,funicular.LowerStation,funicular.UpperStation,nodes,regions,routes,transfers);
    Undo.RecordObject(crowd,"Redistribute 750 NPCs");var registry=root.GetComponent<CityPopulationNavigation>();Undo.RecordObject(registry,"Update castle navigation");registry.Data=data;var transit=root.GetComponent<CityCrowdTransit>();if(!transit)transit=Undo.AddComponent<CityCrowdTransit>(root);Undo.RecordObject(transit,"Connect NPC transport");transit.Elevator=elevator;transit.Funicular=funicular;transit.Transfers=transfers.ToArray();crowd.Transit=transit;crowd.Routes=routes.ToArray();crowd.People=new CityCrowdPerson[750];crowd.PopulationLimit=750;crowd.DrawDistance=550;crowd.DetailDistance=55;var random=new System.Random(21421);int[] totals={250,300,200};int index=0;
    for(int region=0;region<3;region++){var local=routes.Select((r,i)=>new{r,i}).Where(x=>x.r.Region==region&&x.r.CircleNext>=0).Select(x=>x.i).ToArray();var departures=routes.Select((r,i)=>new{r,i}).Where(x=>x.r.Region==region&&x.r.Transfer>=0).Select(x=>x.i).ToArray();for(int j=0;j<totals[region];j++){int route=j<departures.Length*8?departures[j%departures.Length]:local[random.Next(local.Length)];var p=new CityCrowdPerson{Route=route,Skin=roleSkins.Length==750?roleSkins[index]:index%crowd.Appearances.Length,Role=roleNames.Length==750?roleNames[index]:null,NextTripAt=30+index%180,Speed=1.05f+(float)random.NextDouble()*.5f,Lane=((float)random.NextDouble()-.5f)*.4f};p.Distance=(float)random.NextDouble()*routes[route].Length;CityCrowdManager.Locate(routes[route],p.Distance,p.Lane,out p.Position,out p.Yaw);crowd.People[index++]=p;}}
    if(crowd.EditorPreview)Undo.DestroyObjectImmediate(crowd.EditorPreview);var preview=new GameObject("Castle And City NPC Scene Previews - Hidden In Play");Undo.RegisterCreatedObjectUndo(preview,"Preview castle NPCs");preview.transform.SetParent(root.transform,false);crowd.EditorPreview=preview;int[] previewIndices=Enumerable.Range(0,48).Select(i=>i*750/48).ToArray();foreach(int i in previewIndices){var p=crowd.People[i];var g=new GameObject("NPC Preview "+i);g.transform.SetParent(preview.transform,false);g.transform.SetPositionAndRotation(p.Position,Quaternion.Euler(0,p.Yaw,0));var a=crowd.Appearances[p.Skin];for(int part=0;part<a.PoseA.Length;part++){var piece=new GameObject("Walking Skin "+part);piece.transform.SetParent(g.transform,false);piece.AddComponent<MeshFilter>().sharedMesh=a.PoseA[part];piece.AddComponent<MeshRenderer>().sharedMaterial=a.Materials[part];}}
    Undo.RecordObject(root,"Rename 750 NPC population");root.name="Synty Walking Castle And City Population 750";foreach(var item in new UnityEngine.Object[]{crowd,registry,transit})EditorUtility.SetDirty(item);for(int i=0;i<original.Length;i++)if(original[i].localToWorldMatrix!=matrices[i])throw new InvalidOperationException("Existing model moved; rollback required.");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new IOException("Save failed.");Directory.CreateDirectory("Logs");File.WriteAllText("Logs/RedistributeCastleCrowd-report.txt","Placed 750 Synty NPCs: 250 outside city, 300 castle house ring, 200 upper castle/chapel courtyard. Large circular walking circuits in all three regions, with purposeful walks to transport stations. Road nodes: "+string.Join(",",counts)+". Cached routes: "+routes.Count+". Four directional boarding/exit connections validated for actual elevator and funicular. Elevator batches up to 4, funicular batches up to 6; queues capped at 12 per direction. NPC passengers follow actual deck positions. Existing models unchanged. 48 Scene previews. Draw distance 550m. Live transport and crowd behavior require Play-mode observation.\nBackup: "+backup);Debug.Log("500 NPCs inside castle, 250 outside; elevator and funicular crowd routes installed. Enter Play to observe boarding.");SceneView.RepaintAll();
   }
   finally{if(temp.valid)temp.Remove();}
  }
  static bool IsStreetGuide(MeshFilter f)=>f.name.StartsWith("Neighborhood Loop")||f.name.StartsWith("Market Street")||f.name=="Funicular Approach Road";
  static void AddCircuits(List<Vector3> nodes,List<int> regions,List<CityCrowdRoute> routes)
  {
   for(int region=0;region<3;region++){var members=Enumerable.Range(0,nodes.Count).Where(i=>regions[i]==region).ToArray();Vector3 center=Vector3.zero;foreach(int node in members)center+=nodes[node];center/=members.Length;var ring=new List<int>();for(int sector=0;sector<24;sector++){int best=-1;float far=-1;foreach(int node in members){var d=nodes[node]-center;float a=Mathf.Repeat(Mathf.Atan2(d.z,d.x),Mathf.PI*2);if(Mathf.FloorToInt(a/(Mathf.PI*2)*24)!=sector)continue;float distance=d.x*d.x+d.z*d.z;if(distance>far){far=distance;best=node;}}if(best>=0)ring.Add(best);}if(ring.Count<8)throw new InvalidOperationException("Cannot create broad circular walking circuit in region "+region);var circle=new List<int>();for(int i=0;i<ring.Count;i++){int from=ring[i],to=ring[(i+1)%ring.Count];var path=PathBetween(nodes[from],nodes[to]);circle.Add(routes.Count);routes.Add(new CityCrowdRoute{From=from,To=to,Region=region,Transfer=-1,Corners=path,Length=Length(path)});}for(int i=0;i<circle.Count;i++)routes[circle[i]].CircleNext=circle[(i+1)%circle.Count];}
  }
  static Mesh BuildStationGroundApproach(CastleFunicular lift,Transform roads)
  {
   var steps=lift.GetComponentsInChildren<BoxCollider>().Where(c=>c.name.StartsWith("Forest Access Step ")).OrderBy(c=>c.bounds.max.y).ToArray();if(steps.Length==0)throw new InvalidOperationException("Funicular access stairs missing.");Vector3 start=steps[0].bounds.center;start.y=GroundHeight(start);Vector3 end=Vector3.zero;float closest=float.MaxValue;foreach(var f in roads.GetComponentsInChildren<MeshFilter>().Where(IsStreetGuide)){var v=f.sharedMesh.vertices;for(int i=0;i+1<v.Length;i+=2){var point=f.transform.TransformPoint((v[i]+v[i+1])*.5f);float d=Vector3.ProjectOnPlane(point-start,Vector3.up).sqrMagnitude;if(Mathf.Abs(point.y-start.y)<3&&d<closest){closest=d;end=point;}}}if(closest==float.MaxValue)throw new InvalidOperationException("No city road beside station stairs.");int count=Mathf.Max(2,Mathf.CeilToInt(Vector3.Distance(start,end)/.5f));var vertices=new List<Vector3>();var triangles=new List<int>();Vector3 side=Vector3.Cross(Vector3.up,(end-start).normalized);for(int i=0;i<=count;i++){var center=Vector3.Lerp(start,end,(float)i/count);foreach(float edge in new[]{-1.7f,1.7f}){var point=center+side*edge;point.y=GroundHeight(point)+.04f;if(i==count)point.y=end.y;vertices.Add(point);}if(i<count){int a=i*2;triangles.AddRange(new[]{a,a+2,a+1,a+1,a+2,a+3});}}var mesh=new Mesh{name="Navigation Only Existing Ground Approach"};mesh.SetVertices(vertices);mesh.SetTriangles(triangles,0);mesh.RecalculateBounds();return mesh;
  }
  static float GroundHeight(Vector3 point){foreach(var terrain in Terrain.activeTerrains){var origin=terrain.transform.position;var size=terrain.terrainData.size;if(point.x>=origin.x&&point.x<=origin.x+size.x&&point.z>=origin.z&&point.z<=origin.z+size.z)return terrain.SampleHeight(point)+origin.y;}throw new InvalidOperationException("No ground under funicular approach.");}
  static void ConnectTransport(int vehicle,int lowerRegion,int upperRegion,Vector3 lower,Vector3 upper,List<Vector3> nodes,List<int> regions,List<CityCrowdRoute> routes,List<CityCrowdTransfer> transfers)
  {
   int from,to;var lowerApproach=StationApproach(lower,lowerRegion,nodes,regions,out from);var upperApproach=StationApproach(upper,upperRegion,nodes,regions,out to);for(int direction=0;direction<2;direction++){bool reverse=direction==1;int start=reverse?to:from,end=reverse?from:to;var approach=reverse?upperApproach:lowerApproach;var arrival=reverse?lowerApproach:upperApproach;var exit=Enumerable.Reverse(arrival).ToArray();var waiting=approach[approach.Length-1];int transfer=transfers.Count;transfers.Add(new CityCrowdTransfer{Vehicle=vehicle,FromUpper=reverse,FromNode=start,ToNode=end,Waiting=waiting,QueueDirection=Vector3.ProjectOnPlane(approach[approach.Length-2]-waiting,Vector3.up).normalized,Exit=exit});routes.Add(new CityCrowdRoute{From=start,To=end,Region=reverse?upperRegion:lowerRegion,Transfer=transfer,Corners=approach,Length=Length(approach)});}

  }
  static Vector3[] StationApproach(Vector3 station,int region,List<Vector3> nodes,List<int> regions,out int node)
  {
   station.y+=.025f;var candidates=new List<Vector3>{station};for(int radius=1;radius<=12;radius++)for(int angle=0;angle<24;angle++){float a=angle*Mathf.PI*2/24;candidates.Add(station+new Vector3(Mathf.Cos(a)*radius,0,Mathf.Sin(a)*radius));}
   foreach(var candidate in candidates){if(!NavMesh.SamplePosition(candidate,out NavMeshHit hit,.9f,1)||Mathf.Abs(hit.position.y-station.y)>.4f||!SupportedLandingSegment(hit.position,station))continue;foreach(int i in Enumerable.Range(0,nodes.Count).Where(i=>regions[i]==region).OrderBy(i=>Vector3.Distance(nodes[i],hit.position)).Take(12)){var path=new NavMeshPath();if(!NavMesh.CalculatePath(nodes[i],hit.position,1,path)||path.status!=NavMeshPathStatus.PathComplete)continue;node=i;var points=path.corners.ToList();if(points.Count==0)points.Add(nodes[i]);if(Vector3.Distance(points[points.Count-1],station)>.03f)points.Add(station);if(points.Count<2)points.Insert(0,nodes[i]);return points.ToArray();}}
   node=-1;throw new InvalidOperationException("No supported, unobstructed landing connection for region "+region+" at "+station);
  }
  static bool SupportedLandingSegment(Vector3 a,Vector3 b)
  {
   var delta=b-a;float length=delta.magnitude;if(length>.03f){var collisions=Physics.CapsuleCastAll(a+Vector3.up*.36f,a+Vector3.up*1.44f,.27f,delta.normalized,length,~0,QueryTriggerInteraction.Ignore);if(collisions.Any(h=>h.collider&&h.collider.enabled))return false;}int samples=Mathf.Max(1,Mathf.CeilToInt(length/.3f));for(int j=0;j<=samples;j++){var point=Vector3.Lerp(a,b,(float)j/samples);var hits=Physics.RaycastAll(point+Vector3.up*.22f,Vector3.down,.55f,~0,QueryTriggerInteraction.Ignore);if(!hits.Any(h=>h.normal.y>.7f&&Mathf.Abs(h.point.y-point.y)<.18f))return false;}return true;
  }
  static Vector3[] PathBetween(Vector3 a,Vector3 b){var path=new NavMeshPath();if(!NavMesh.CalculatePath(a,b,1,path)||path.status!=NavMeshPathStatus.PathComplete)throw new InvalidOperationException("Walking connection is blocked.");return path.corners.Length>=2?path.corners:new[]{a,b};}
  static float Length(Vector3[] points){float length=0;for(int i=1;i<points.Length;i++)length+=Vector3.Distance(points[i-1],points[i]);return length;}
 }
